-- 001_init: base schema.
--
-- Conventions:
--   * ids are UUID strings (TEXT), generated by the server (uuid.NewV7).
--   * *_at columns are Unix time in milliseconds (UTC).
--   * paths are stored relative to the library root, with '/' separators.
--   * the server never renames, moves or deletes user files: everything here
--     is a virtual view of the media folder.

CREATE TABLE libraries (
    id         TEXT    PRIMARY KEY,
    name       TEXT    NOT NULL,
    root_path  TEXT    NOT NULL UNIQUE,
    created_at INTEGER NOT NULL
) STRICT;

-- One row per file found on disk (main media, trailers and extras).
CREATE TABLE media_files (
    id            TEXT    PRIMARY KEY,
    library_id    TEXT    NOT NULL REFERENCES libraries (id) ON DELETE CASCADE,
    rel_path      TEXT    NOT NULL,
    size          INTEGER NOT NULL,
    mtime_ns      INTEGER NOT NULL,
    partial_hash  TEXT,                 -- first + last 64 KB, to follow moved/renamed files
    kind          TEXT    NOT NULL DEFAULT 'unknown'
                  CHECK (kind IN ('movie', 'episode', 'trailer', 'extra', 'unknown')),
    status        TEXT    NOT NULL DEFAULT 'ok'
                  CHECK (status IN ('ok', 'review', 'ignored', 'missing')),
    -- ffprobe results (filled by the scanner, NULL until probed)
    container     TEXT,
    duration_ms   INTEGER,
    width         INTEGER,
    height        INTEGER,
    video_codec   TEXT,
    audio_codec   TEXT,                 -- codec of the default audio track
    hdr           TEXT,                 -- NULL, 'hdr10', 'hlg', 'dolby_vision'...
    bitrate       INTEGER,
    probe_json    TEXT,                 -- full ffprobe output (tracks, chapters)
    probed_at     INTEGER,
    -- local artwork found next to the file
    image_path    TEXT,
    dominant_color TEXT,
    added_at      INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL,
    UNIQUE (library_id, rel_path)
) STRICT;

CREATE INDEX media_files_status_idx  ON media_files (status);
CREATE INDEX media_files_hash_idx    ON media_files (size, partial_hash);
CREATE INDEX media_files_added_idx   ON media_files (added_at);

CREATE TABLE movies (
    id            TEXT    PRIMARY KEY,
    media_file_id TEXT    NOT NULL UNIQUE REFERENCES media_files (id) ON DELETE CASCADE,
    title         TEXT    NOT NULL,
    sort_title    TEXT    NOT NULL,
    norm_title    TEXT    NOT NULL,     -- lowercase, no accents, no punctuation
    year          INTEGER,
    poster_path   TEXT,
    fanart_path   TEXT,
    added_at      INTEGER NOT NULL
) STRICT;

CREATE INDEX movies_sort_idx  ON movies (sort_title);
CREATE INDEX movies_year_idx  ON movies (year);
CREATE INDEX movies_added_idx ON movies (added_at);

-- Series and anime share the same shape; kind tells them apart.
CREATE TABLE series (
    id          TEXT    PRIMARY KEY,
    kind        TEXT    NOT NULL CHECK (kind IN ('series', 'anime')),
    title       TEXT    NOT NULL,
    sort_title  TEXT    NOT NULL,
    norm_title  TEXT    NOT NULL,
    year        INTEGER,
    poster_path TEXT,
    fanart_path TEXT,
    added_at    INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL,
    UNIQUE (kind, norm_title)
) STRICT;

CREATE INDEX series_sort_idx  ON series (kind, sort_title);
CREATE INDEX series_added_idx ON series (updated_at);

CREATE TABLE seasons (
    id          TEXT    PRIMARY KEY,
    series_id   TEXT    NOT NULL REFERENCES series (id) ON DELETE CASCADE,
    number      INTEGER NOT NULL,       -- 0 = specials
    title       TEXT,
    poster_path TEXT,
    UNIQUE (series_id, number)
) STRICT;

CREATE TABLE episodes (
    id              TEXT    PRIMARY KEY,
    series_id       TEXT    NOT NULL REFERENCES series (id) ON DELETE CASCADE,
    season_id       TEXT    NOT NULL REFERENCES seasons (id) ON DELETE CASCADE,
    media_file_id   TEXT    NOT NULL UNIQUE REFERENCES media_files (id) ON DELETE CASCADE,
    number          INTEGER,            -- episode number inside the season
    number_end      INTEGER,            -- last episode of a multi-episode file (S01E01-E02)
    absolute_number INTEGER,            -- anime absolute numbering
    version         INTEGER,            -- release version (v2)
    title           TEXT,
    added_at        INTEGER NOT NULL
) STRICT;

CREATE INDEX episodes_season_idx ON episodes (season_id, number);
CREATE INDEX episodes_series_idx ON episodes (series_id, absolute_number);
CREATE INDEX episodes_added_idx  ON episodes (added_at);

CREATE TABLE subtitles (
    id            TEXT    PRIMARY KEY,
    media_file_id TEXT    NOT NULL REFERENCES media_files (id) ON DELETE CASCADE,
    source        TEXT    NOT NULL CHECK (source IN ('external', 'embedded')),
    rel_path      TEXT,                 -- external: sidecar file path
    stream_index  INTEGER,              -- embedded: ffprobe stream index
    language      TEXT,                 -- BCP 47 when known (pt-BR, en, ja)
    codec         TEXT    NOT NULL,     -- srt, ass, ssa, webvtt, pgs...
    title         TEXT,
    is_forced     INTEGER NOT NULL DEFAULT 0,
    is_default    INTEGER NOT NULL DEFAULT 0,
    CHECK ((source = 'external' AND rel_path IS NOT NULL)
        OR (source = 'embedded' AND stream_index IS NOT NULL))
) STRICT;

CREATE INDEX subtitles_media_idx ON subtitles (media_file_id);

CREATE TABLE profiles (
    id                 TEXT    PRIMARY KEY,
    name               TEXT    NOT NULL UNIQUE,
    color              TEXT    NOT NULL,   -- avatar color
    pin_hash           TEXT,                -- optional 4-digit PIN (hashed)
    subtitle_language  TEXT,                -- default subtitle language
    audio_language     TEXT,                -- preferred audio language
    reduce_motion      INTEGER NOT NULL DEFAULT 0,
    created_at         INTEGER NOT NULL
) STRICT;

CREATE TABLE progress (
    profile_id    TEXT    NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
    media_file_id TEXT    NOT NULL REFERENCES media_files (id) ON DELETE CASCADE,
    position_ms   INTEGER NOT NULL DEFAULT 0,
    duration_ms   INTEGER NOT NULL DEFAULT 0,
    watched       INTEGER NOT NULL DEFAULT 0,
    audio_stream  INTEGER,                 -- last chosen tracks
    subtitle_id   TEXT,
    updated_at    INTEGER NOT NULL,
    PRIMARY KEY (profile_id, media_file_id)
) STRICT;

-- "Continue watching": latest unfinished items of a profile.
CREATE INDEX progress_recent_idx ON progress (profile_id, watched, updated_at DESC);
